window.PROJECTS=[{"id": "workforce", "n": "01", "title": "근태·채용 관리 시스템", "sub": "매장 운영의 규칙을 서비스로", "tag": "SYSTEM DESIGN · CLOUD OPERATIONS", "role": "요구사항·구조 설계 / AI 활용 구현 / 배포·운영", "status": "회사 경험 · 매장 운영 시스템 프로젝트 · 2026.02–현재", "type": "company", "color": "orange", "desc": "근태·스케줄·채용 흐름을 연결하고, 운영 간섭을 줄이기 위해 AWS 환경과 배포 방식을 변경했습니다.", "summary": "매장 운영 요구를 업무 규칙과 시스템 구조로 구체화하고, 서비스 운영 중 드러난 문제에 대응한 경험입니다. 주요 설계와 운영 방향을 결정하고, 코드·워크플로우 구현에는 Claude Code를 활용했습니다.", "flow": ["사용자 요구·업무 규칙", "시스템·화면 흐름 설계", "AI 활용 구현", "배포·운영·변경 대응"], "sections": [["채용과 직원 관리를 하나의 흐름으로", ["서비스 계정과 조직 소속을 구분하고 지원자 파이프라인, 이력서·메모 조회, 면접 일정과 이메일 안내를 연결했습니다.", "채용 확정 시 조직 멤버 전환과 지원 매장 배정으로 이어지는 흐름을 구성했습니다.", "관리자 스케줄을 기준으로 태블릿 출퇴근 처리와 직원용 웹 스케줄 조회를 구성하고, 직원번호·시급의 관리 단위를 매장별에서 그룹 기준으로 변경했습니다."]], ["운영 문제에서 환경 분리로", ["초기에는 사용량과 비용을 고려해 동일한 EC2·RDS 인스턴스에서 staging과 production을 운영했습니다.", "staging 배포, cron 실행, CPU·메모리 부족과 DB 병목 등이 실제 운영에 영향을 줬습니다. 이를 계기로 두 환경의 EC2·RDS를 분리했습니다.", "staging을 필요할 때만 기동하고, 기동·중지·production DB 기준 동기화를 실행할 수 있도록 GitHub Actions 워크플로우를 구성했습니다."]], ["배포·운영 방식의 변경", ["production EC2를 상위 사양으로 이전하고, RDS 변경은 서비스 미사용 시간대인 새벽에 예약 적용했습니다.", "ALB 기반 EC2 무중단 배포를 적용했습니다. S3로 서버 코드·직원용 웹 앱·출퇴근 태블릿 앱(출퇴근 태블릿 앱)의 배포 버전을 관리하고, 웹 앱 제공에 CloudFront를 적용했습니다."]], ["본인의 역할과 구현 도구", ["요구사항·업무 규칙, 시스템 구조·화면 흐름, 환경 분리와 staging 운영 방식을 직접 설계·적용했습니다.", "Claude Code로 대안을 검토하고 실행 방법을 확인했으며, 코드·워크플로우 작성과 수정에는 AI를 활용했습니다."]], ["운영 구조 개선 결과", ["staging과 production의 EC2·RDS를 분리해 환경 간 운영 간섭에 대응하고, staging은 필요할 때 기동하는 방식으로 변경했습니다."]]], "stack": ["AWS EC2", "RDS", "S3", "CloudFront", "IAM", "ALB", "GitHub Actions"], "diagram": "infra"}, {"id": "vision", "n": "02", "title": "영상 분석 파이프라인", "sub": "라벨 생성부터 실시간 결과 전달까지", "tag": "VIDEO PIPELINE · PERFORMANCE", "role": "기존 코드 분석·개선 / 모델 실행·학습 / 서버 연계", "status": "회사 경험 · AI 서비스 개발 프로젝트 · 2025.06–2026.02", "type": "company", "color": "green", "desc": "오토라벨링의 병목을 추적하고, RTSP 영상 분석 결과를 Kafka·Redis와 연계해 전달했습니다.", "summary": "영상 분석 모델을 실제 처리 흐름에 연결하고, 기존 오토라벨링의 성능 문제를 모듈 단위로 추적해 개선했습니다. 모델 자체 연구보다 실행·데이터 처리·결과 연계에 집중한 경험입니다.", "flow": ["군중 모델 점 좌표·밀도 맵", "박스 후보 생성·조정", "YOLO로 사람 여부 검증", "유효 라벨 좌표 저장"], "sections": [["오토라벨링: 품질과 속도를 함께 개선", ["스포츠 경기·대형 축제·항만 등 여러 환경의 CCTV 영상을 사용했습니다. 군중 모델의 점 좌표·밀도 맵으로 박스 후보를 생성·조정하고, 후보 영역을 잘라 YOLO로 사람 여부를 확인한 뒤 유효한 라벨 좌표를 저장하는 흐름을 개선했습니다.", "박스 크기와 가중치를 테스트하며 조정했습니다. 영상 추출·점 좌표 생성·박스 생성 모듈을 개별 실행하고 코드를 단계별로 디버깅해 병목을 좁혔습니다.", "Claude 웹에 코드를 질문하며 개선 대안을 검토하고 탐색 구조를 변경했습니다. 당시에는 Claude Code가 아닌 웹 대화를 활용했습니다."]], ["결과: 다음 날까지 미완료 → 1시간 이내", ["다음 날까지 완료되지 않기도 하던 작업을 당시 테스트에서 1시간 이내에 완료하도록 개선했습니다.", "당시 테스트 경험에 따른 결과입니다. 동일 영상·실행 환경에 대한 벤치마크 기록이 없어 개선 배수는 산정하지 않았습니다."]], ["RTSP 실시간 분석과 결과 전달", ["대형 축제 CCTV의 RTSP 영상을 입력받아 군중 분석 모델을 실행하고 인원수·분포 관련 결과를 수집했습니다.", "H100 서버에서 모델별 분석 프로세스를 동시에 실행하고, Kafka·Redis와 연계해 시각화·이상상황 감지 프로그램 서버로 결과를 전달했습니다.", "분석 결과를 기존 시각화 프로그램과 연계하는 서버 측 처리를 담당했습니다."]], ["이상상황 학습·시연의 범위", ["쓰러짐·화재·싸움 등 이상상황별 데이터를 수집·보완하고 관련 모델 학습을 수행했습니다. 사례가 부족한 유형은 YouTube 영상으로 보완하고, 감지가 잘되는 선별 영상으로 기능 시연을 진행했습니다.", "저화질 CCTV에서 특정 인물 추적도 시도했지만 요구 수준을 확보하지 못해 중단했습니다."]]], "stack": ["Python", "YOLO", "Crowd model", "RTSP", "H100", "Kafka", "Redis"], "diagram": "vision"}, {"id": "document-ai", "n": "03", "title": "문서·음성 AI API", "sub": "실험 코드를 서비스에서 호출할 수 있도록", "tag": "AI INTEGRATION · BACKEND", "role": "파이프라인 인수·개선 / API 구성 / HTTPS 배포", "status": "회사 경험 · AI 서비스 개발 프로젝트 · 2025.06–2026.02", "type": "company", "color": "purple", "desc": "기존 AI 처리 코드를 인수해 실행·정제 흐름을 개선하고, API 서버와 HTTPS 환경을 단독 구성했습니다.", "summary": "매뉴얼·양식 관련 AI 질의응답 서비스 과제에서 문서·음성 처리 파이프라인을 인수했습니다. 모델을 새로 연구하는 대신, 기존 기능을 안정적으로 호출할 수 있는 백엔드로 연결하는 일을 맡았습니다.", "flow": ["문서·음성 입력", "AI 모델 실행", "추출·정제·형식 변환", "서비스 API 제공"], "sections": [["기존 파이프라인을 인수해 재구성", ["API별 AI 처리 흐름과 데이터 정제 과정을 점검·수정했습니다. 여러 OCR 모델의 단독·조합 적용을 테스트하고 Markdown·JSON 형태의 결과를 다뤘습니다.", "음성 인식 모델의 실행 설정과 일부 파라미터를 조정했습니다."]], ["처리 지연과 한글 인식 문제 개선", ["요청마다 모델을 다시 로드하던 실행 구조를 개선하고, OCR·음성 관련 기능과 PDF 분석·Markdown 변환의 처리 시간을 단축했습니다.", "한글 인식 오류를 코드 디버깅과 자료 조사로 추적하고 관련 파일 교체를 통해 인식 품질을 개선했습니다."]], ["API와 HTTPS 배포를 단독 담당", ["Node.js API 서버를 구축하고 Nginx 리버스 프록시·Certbot 기반 HTTPS 환경을 구성·배포했습니다.", "AI 기능을 서비스에서 호출할 수 있도록 API 구성과 배포 작업을 단독으로 담당했습니다."]]], "stack": ["Python", "Node.js", "Nginx", "Certbot", "OCR", "Speech AI", "Markdown / JSON"], "diagram": "document"}, {"id": "visitor-analytics", "n": "04", "title": "CCTV 방문객 분석", "sub": "분석 결과를 읽을 수 있는 도구로", "tag": "DATA VIEWER · AI REPORT", "role": "영상 분석 / WinForms 뷰어 / 보고서·LLM API 연동", "status": "개별 수행 프로젝트 · 약 1개월", "type": "company", "color": "blue", "desc": "방문객 통계를 화면에서 비교하고, HTML 보고서와 AI 분석 문구로 활용하도록 연결했습니다.", "summary": "CCTV 영상에서 YOLO로 사람을 탐지하고 별도 모델로 성별·나이대를 추정한 결과를 Python에서 조합해 방문객 통계를 생성했습니다. 이를 조회·비교하는 뷰어와 보고서로 연결했습니다.", "flow": ["CCTV 영상", "YOLO 사람 탐지 + 별도 모델 성별·나이대 추정", "Python 통계 집계", "WinForms 조회·비교 / HTML·AI 보고서"], "sections": [["분석을 사용 가능한 결과로", ["YOLO 기반 사람 탐지와 별도 모델의 성별·나이대 추정 결과를 Python에서 조합해 방문객 통계를 생성했습니다.", "WinForms 뷰어에서 CCTV별 데이터 조회와 시간대별 통계 비교 기능을 구현했습니다.", "통계 기반 HTML 보고서와 ChatGPT API를 활용한 분석 문구 생성 기능을 구성했습니다."]], ["역할과 범위", ["영상 분석 → 통계 → 뷰어 → 보고서로 이어지는 개별 프로젝트를 약 한 달간 진행했습니다.", "ChatGPT API는 개발 보조 도구 사용과 별개로 결과 보고서의 분석 문구를 생성하는 제품 기능에 적용했습니다."]]], "stack": ["Python", "YOLO", "WinForms", "ChatGPT API", "HTML"], "diagram": "document"}, {"id": "secrets", "n": "05", "title": "팀 시크릿 관리 서비스", "sub": "팀 시크릿 공유의 경계를 설계하다", "tag": "PERSONAL · DESIGN IN PROGRESS", "role": "문제 정의 / 설계·문서화", "status": "개인 프로젝트 · 구현 준비", "type": "personal", "color": "green", "desc": "권한·암호화 경계·버전 충돌과 복구 흐름을 정리한 팀 시크릿 관리 서비스 설계입니다.", "summary": "팀의 .env·키파일 공유 문제를 정의하고, AI와 대안을 비교하며 서비스 구조를 설계·문서화했습니다. 현재는 구현 준비 단계입니다.", "flow": ["팀 시크릿 공유 문제", "권한·암호화 경계", "버전 충돌·감사 로그", "작은 구현 → 직접 리뷰 계획"], "sections": [["설계한 범위", ["권한·암호화 경계·복구 흐름과 버전 충돌 처리, 감사 로그·트랜잭션 경계를 문서화했습니다.", "현재 설계·문서화 단계이며, 구현과 검증을 준비하고 있습니다."]], ["다음 단계", ["작은 단위의 구현마다 선택 이유와 직접 리뷰한 내용, 수정한 점과 확인 결과를 남기는 방식으로 진행할 계획입니다."]]], "stack": ["Requirements", "Architecture", "Documentation"], "diagram": "document"}, {"id": "file-tools", "n": "06", "title": "브라우저 파일 처리 도구", "sub": "AI로 만든 도구를 실제로 공개하다", "tag": "PERSONAL · LIVE EXPERIMENT", "role": "서비스 방향 / 아이디어 / 결과 조정", "status": "개인 프로젝트 · 공개 서비스", "type": "personal", "color": "purple", "desc": "AI 중심으로 제작한 파일 처리 도구 서비스. 맡긴 범위와 본인의 판단을 구분한 제작 실험입니다.", "summary": "파일 처리 도구 서비스의 방향과 아이디어를 제시하고, 의도와 다른 결과를 조정하며 공개했습니다. 세부 설계·구현은 주로 AI가 수행했습니다.", "flow": ["방향·중점 제시", "AI의 도구 선정·구현", "Codex Review·AI 수정", "결과 조정·공개"], "sections": [["본인의 역할", ["서비스 방향과 보안상 중점을 제시하고 아이디어 추가, 의도와 다른 결과 조정을 담당했습니다.", "도구 선정·세부 설계·구현은 주로 AI가 수행했습니다. Codex Review를 활용해 검토하고 AI로 수정했습니다."]], ["사용된 기술", ["서비스에는 Astro·Svelte·TypeScript·Cloudflare가 적용됐습니다."]]], "stack": ["Astro", "Svelte", "TypeScript", "Cloudflare"], "diagram": "document"}];
